import { Box, Text, Switch } from '@gravity-ui/uikit';

export interface SettingsPageProps {
  isDark: boolean;
  onToggleTheme: (checked: boolean) => void;
}

export function SettingsPage({ isDark, onToggleTheme }: SettingsPageProps) {
  return (
    <Box spacing={{ p: 4 }}>
      <Text variant=\"header-1\" as=\"h1\">
        Settings
      </Text>
      <Box spacing={{ mt: 4 }}>
        <Switch checked={isDark} onChange={(e) => onToggleTheme(e.target.checked)} content=\"Dark theme\" size=\"l\" />
      </Box>
    </Box>
  );
}
ENDOFFILE"

/bin/bash -lc "cat > src/App.tsx << 'ENDOFFILE'
import { useState, useCallback } from 'react';
import {
  ThemeProvider,
  Flex,
  Text,
  TabProvider,
  TabList,
  Tab,
  TabPanel,
  Button,
  Icon,
} from '@gravity-ui/uikit';
import { HouseIcon } from '@gravity-ui/icons';
import { CircleInfoIcon } from '@gravity-ui/icons';
import { GearIcon } from '@gravity-ui/icons';
import type { RealTheme } from '@gravity-ui/uikit';

import { HomePage } from './pages/HomePage';
import { AboutPage } from './pages/AboutPage';
import { SettingsPage } from './pages/SettingsPage';

import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

export function App() {
  const [theme, setTheme] = useState<RealTheme>('light');
  const [activeTab, setActiveTab] = useState('home');

  const toggleTheme = useCallback((checked: boolean) => {
    setTheme(checked ? 'dark' : 'light');
  }, []);

  return (
    <ThemeProvider theme={theme}>
      <Flex direction=\"column\" style={{ minHeight: '100vh' }}>
        <Flex
          as=\"header\"
          alignItems=\"center\"
          justifyContent=\"space-between\"
          style={{
            padding: '8px 24px',
            borderBottom: '1px solid var(--g-color-line-generic)',
            flexShrink: 0,
          }}
        >
          <Text variant=\"header-1\">Gravity UI Demo</Text>
        </Flex>

        <TabProvider value={activeTab} onUpdate={setActiveTab}>
          <Flex
            style={{
              padding: '0 24px',
              borderBottom: '1px solid var(--g-color-line-generic)',
              flexShrink: 0,
            }}
          >
            <TabList>
              <Tab value=\"home\" icon={<Icon data={HouseIcon} />}>
                Home
              </Tab>
              <Tab value=\"about\" icon={<Icon data={CircleInfoIcon} />}>
                About
              </Tab>
              <Tab value=\"settings\" icon={<Icon data={GearIcon} />}>
                Settings
              </Tab>
            </TabList>
          </Flex>

          <main style={{ flex: 1, minHeight: 0 }}>
            <TabPanel value=\"home\">
              <HomePage />
            </TabPanel>
            <TabPanel value=\"about\">
              <AboutPage />
            </TabPanel>
            <TabPanel value=\"settings\">
              <SettingsPage isDark={theme === 'dark'} onToggleTheme={toggleTheme} />
            </TabPanel>
          </main>
        </TabProvider>
      </Flex>
    </ThemeProvider>
  );
}
ENDOFFILE"

